package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.service.jobs.GenerationFlowService.Stage;
import com.lianxibu.site.service.jobs.ResultApplicationService.Input;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;

/** All proof references are fictional. Tests exercise original INPUT constraints, not native admission. */
class CatalogDedupResultV2Test {
    ObjectNode context(Stage stage,Boolean changed){var root=new FrozenCatalogVersionContextTest().context(stage);if(changed==null)root.putArray("catalog_version_qualifications");else ((ObjectNode)root.get("catalog_version_qualifications").get(0)).put("version_changed",changed);if(!Boolean.TRUE.equals(changed))root.putArray("version_eligible_item_ids");return root;}
    Input input(Stage stage,Boolean changed){return FrozenApplicationContext.fromJson(context(stage,changed)).input("fictional-root","fictional-attempt","c".repeat(64),0);}
    ObjectNode payload(Stage stage,Boolean changed){var root=JsonMapper.shared().createObjectNode().put("kind","dedup").put("dedup_result_version","2").put("summary","Fictional comparison summary");var item=root.putArray("items").addObject().put("item_id","fictional-item").put("category",stage.name().toLowerCase(Locale.ROOT).replace("_dedup","")).put("decision","existing").put("candidate_entity_id","fictional-entity").put("reason","Fictional comparison").put("confidence","1").put("suggested_title","Fictional object").putNull("suggested_summary").put("reanalyze_recommended",Boolean.TRUE.equals(changed));if(changed==null){item.putNull("version_changed").putNull("previous_evidence_ref").putNull("new_evidence_ref");}else{item.put("version_changed",changed);item.putObject("previous_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash","a".repeat(64));item.putObject("new_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash","b".repeat(64));}return root;}
    ObjectNode item(ObjectNode p){return (ObjectNode)p.get("items").get(0);}
    String json(ObjectNode p){return new String(CanonicalJson.bytes(p),java.nio.charset.StandardCharsets.UTF_8);}
    void accept(Input i,ObjectNode p){String raw=ResultApplicationService.providerEnvelope(i,json(p));var v=ResultApplicationService.validate(i,raw);assertEquals("dedup",v.kind());assertEquals(CanonicalJson.parse(json(p)),CanonicalJson.parse(v.payloadJson()));}
    void reject(Input i,ObjectNode p){assertThrows(ResultApplicationService.Rejected.class,()->ResultApplicationService.providerEnvelope(i,json(p)));}
    @Test void FourCatalogKnownTrueRequiresOriginalRefsAndMayRecommendEitherBoolean(){for(var stage:List.of(Stage.AGENT_DEDUP,Stage.SKILL_DEDUP,Stage.WORKFLOW_DEDUP,Stage.MODEL_DEDUP)){var p=payload(stage,true);accept(input(stage,true),p);item(p).put("reanalyze_recommended",false);accept(input(stage,true),p);}}
    @Test void KnownFalseCannotChangeNativeFlagOrRecommendReanalysis(){var i=input(Stage.AGENT_DEDUP,false);var p=payload(Stage.AGENT_DEDUP,false);accept(i,p);item(p).put("reanalyze_recommended",true);reject(i,p);item(p).put("reanalyze_recommended",false).put("version_changed",true);reject(i,p);item(p).putNull("version_changed");reject(i,p);}
    @Test void UnknownAndAnotherFrozenCandidateCannotBorrowAnEntityVersionProof(){var i=input(Stage.AGENT_DEDUP,null);var p=payload(Stage.AGENT_DEDUP,null);accept(i,p);item(p).put("version_changed",false);reject(i,p);p=payload(Stage.AGENT_DEDUP,true);reject(i,p);
        var ctx=context(Stage.AGENT_DEDUP,true);((ArrayNode)ctx.get("candidates_by_item").get(0).get("entity_ids")).add("fictional-other-entity");i=FrozenApplicationContext.fromJson(ctx).input("fictional-root","fictional-attempt","c".repeat(64),0);p=payload(Stage.AGENT_DEDUP,null);item(p).put("candidate_entity_id","fictional-other-entity");accept(i,p);item(p).put("version_changed",true);reject(i,p);}
    @Test void NewAndReviewCarryNoVersionOrCandidateEvenForPreviouslyQualifiedItem(){for(String decision:List.of("new","needs_review")){var p=payload(Stage.SKILL_DEDUP,null);item(p).put("decision",decision).putNull("candidate_entity_id");accept(input(Stage.SKILL_DEDUP,true),p);item(p).put("reanalyze_recommended",true);reject(input(Stage.SKILL_DEDUP,true),p);item(p).put("reanalyze_recommended",false).put("candidate_entity_id","fictional-entity");reject(input(Stage.SKILL_DEDUP,true),p);}}
    @Test void SwappedForeignNullExtraWrongKindAndWrongHashProofsRejectEvenWithNewEnvelopeHash(){for(String fault:List.of("swapped","foreign","null","extra","kind","uppercase","flag")){var p=payload(Stage.WORKFLOW_DEDUP,true);var v=item(p);var ref=(ObjectNode)v.get("new_evidence_ref");switch(fault){case "swapped"->{ref.put("proof_hash","a".repeat(64));((ObjectNode)v.get("previous_evidence_ref")).put("proof_hash","b".repeat(64));}case "foreign"->ref.put("proof_hash","d".repeat(64));case "null"->v.putNull("previous_evidence_ref");case "extra"->ref.put("fictional_unknown",true);case "kind"->ref.put("kind","catalog_evidence");case "uppercase"->ref.put("proof_hash","B".repeat(64));case "flag"->v.put("version_changed","true");}reject(input(Stage.WORKFLOW_DEDUP,true),p);}}
    @Test void VersionSelectionIsOriginalAndCannotDowngradeOrCrossStage(){var v2=input(Stage.AGENT_DEDUP,true);var p=payload(Stage.AGENT_DEDUP,true);var old=FrozenApplicationContext.fromJson(CanonicalJson.parse(FrozenApplicationContextTest.context(Stage.AGENT_DEDUP))).input("fictional-root","fictional-attempt","c".repeat(64),0);reject(old,p);p.remove("dedup_result_version");reject(v2,p);p=payload(Stage.AGENT_DEDUP,true);p.put("dedup_result_version","1");reject(v2,p);p.put("dedup_result_version",2);reject(v2,p);p=payload(Stage.AGENT_DEDUP,true);item(p).put("category","skill");reject(v2,p);}
    @Test void FullHundredItemsAreCheckedIncludingLastIllegalProof(){var ctx=context(Stage.MODEL_DEDUP,true);var p=payload(Stage.MODEL_DEDUP,true);ctx.putArray("eligible_high_value_item_ids");var items=ctx.putArray("item_ids");var candidates=ctx.putArray("candidates_by_item");var eligibility=ctx.putArray("version_eligible_item_ids");var quals=ctx.putArray("catalog_version_qualifications");var results=p.putArray("items");var one=item(payload(Stage.MODEL_DEDUP,true));var q=new FrozenCatalogVersionContextTest().context(Stage.MODEL_DEDUP).get("catalog_version_qualifications").get(0);for(int n=0;n<100;n++){String id="fictional-item-"+n;items.add(id);eligibility.add(id);candidates.addObject().put("item_id",id).putArray("entity_ids").add("fictional-entity");var next=(ObjectNode)q.deepCopy();next.put("item_id",id);quals.add(next);var result=one.deepCopy();result.put("item_id",id);results.add(result);}var i=FrozenApplicationContext.fromJson(ctx).input("fictional-root","fictional-attempt","c".repeat(64),0);accept(i,p);((ObjectNode)results.get(99).get("new_evidence_ref")).put("proof_hash","d".repeat(64));reject(i,p);}
    @Test void MissingDuplicateTooManyExtraOrForeignItemsNeverBecomePartialSuccess(){for(String fault:List.of("missing","duplicate","many","extra","foreign")){var p=payload(Stage.AGENT_DEDUP,true);var values=(ArrayNode)p.get("items");switch(fault){case "missing"->values.removeAll();case "duplicate"->values.add(item(p).deepCopy());case "many"->{var sample=item(p).deepCopy();for(int n=0;n<100;n++)values.add(sample.deepCopy());}case "extra"->item(p).put("fictional_unknown",true);case "foreign"->item(p).put("item_id","fictional-foreign");}reject(input(Stage.AGENT_DEDUP,true),p);}}
    @Test void DirectTypedInputCannotForgeMapKeysCandidatesOrChangedEligibility(){var i=input(Stage.AGENT_DEDUP,true);var q=i.catalogVersionQualifications().get("fictional-item");for(String fault:List.of("key","candidate","eligibility")){var direct=new Input(i.rootId(),i.attemptId(),i.stage(),i.generation(),i.inputHash(),0,null,i.itemIds(),fault.equals("candidate")?Map.of():i.candidatesByItem(),i.eligibleHighValueItems(),i.allowedCitationIds(),fault.equals("eligibility")?Set.of():i.versionEligibleItems(),null,null,null,"1","2",fault.equals("key")?Map.of("fictional-foreign",q):i.catalogVersionQualifications());reject(direct,payload(Stage.AGENT_DEDUP,true));}}
    @Test void OriginalV1AndValueV2AreStillSeparateContracts(){var old=FrozenApplicationContext.fromJson(CanonicalJson.parse(FrozenApplicationContextTest.context(Stage.NEWS_DEDUP))).input("fictional-root","fictional-attempt","c".repeat(64),0);var p=payload(Stage.AGENT_DEDUP,null);p.remove("dedup_result_version");item(p).put("category","news_tech").put("decision","new").putNull("candidate_entity_id");item(p).remove("version_changed");item(p).remove("previous_evidence_ref");item(p).remove("new_evidence_ref");accept(old,p);var ctx=(ObjectNode)CanonicalJson.parse(FrozenApplicationContextTest.context(Stage.NEWS_VALUE));ctx.put("value_result_version","2");var v=FrozenApplicationContext.fromJson(ctx).input("fictional-root","fictional-attempt","c".repeat(64),0);var value=JsonMapper.shared().createObjectNode().put("kind","value").put("value_result_version","2").put("summary","Fictional news");value.putArray("items").addObject().put("item_id","fictional-item").put("category","news_tech").put("high_value",true).put("valuable",true).put("reason","Fictional quality");value.putArray("selected_item_ids").add("fictional-item");assertEquals("value",ResultApplicationService.validate(v,ResultApplicationService.providerEnvelope(v,json(value))).kind());}
}
